@dataclass(frozen=True)
class FieldSpec:
    name: str
    annotation: str
    required: bool
    comment: str | None


@dataclass
class ClassSpec:
    name: str
    schema: dict[str, Any]
    fields: list[FieldSpec]
    comment: str | None
    extra: str


class PythonGenerator:
    def __init__(self, schemas: dict[str, dict[str, Any]]) -> None:
        self.schemas = schemas
        self.classes: OrderedDict[str, ClassSpec] = OrderedDict()
        self.enums: OrderedDict[str, list[Any]] = OrderedDict()

    def generate(self) -> str:
        self._add_common_classes()
        for name in PAYLOAD_FILES:
            self._add_object(
                self._payload_class_name(name), self.schemas[f"{name}.json"], f"{name}.json"
            )
        self._add_object("FarmEnvelope", self.schemas["envelope.json"], "envelope.json")

        lines = [*HEADER]
        lines.extend(
            [
                "from __future__ import annotations",
                "",
                "from enum import Enum",
                "from typing import Annotated, Any, Dict, List, Literal, Optional",
                "",
                "from pydantic import BaseModel, ConfigDict, Field",
                "",
                "",
            ]
        )

        for enum_name, values in self.enums.items():
            lines.append(f"class {enum_name}(str, Enum):")
            for value in values:
                if value is None:
                    continue
                lines.append(f"    {self._enum_member(str(value))} = {value!r}")
            lines.append("")
            lines.append("")

        for cls in self.classes.values():
            if cls.comment:
                lines.append("# INVARIANT (must be validated outside generated schema models):")
                for line in cls.comment.splitlines():
                    lines.append(f"#   {line}")
            lines.append(f"class {cls.name}(BaseModel):")
            lines.append(f'    model_config = ConfigDict(extra="{cls.extra}")')
            lines.append("")
            if not cls.fields:
                lines.append("    pass")
            for field in cls.fields:
                if field.comment:
                    for line in field.comment.splitlines():
                        lines.append(f"    # {line}")
                default = "" if field.required else " = None"
                lines.append(f"    {field.name}: {field.annotation}{default}")
            lines.append("")
            lines.append("")

        lines.append("PAYLOAD_MODELS: Dict[str, type[BaseModel]] = {")
        for msg_type in self.schemas["envelope.json"]["properties"]["type"]["enum"]:
            lines.append(f"    {msg_type!r}: {TYPE_TO_PAYLOAD[msg_type]},")
        lines.append("}")
        lines.append("")
        for class_name in self.classes:
            lines.append(f"{class_name}.model_rebuild()")
        lines.append("")
        return "\n".join(lines).rstrip() + "\n"

    def public_symbols(self) -> list[str]:
        return ["PAYLOAD_MODELS", *sorted([*self.enums.keys(), *self.classes.keys()])]

    def _add_common_classes(self) -> None:
        defs = self.schemas["common.json"]["$defs"]
        for name in ["account_info", "symbol_spec", "broker_time_info", "local_limits"]:
            self._add_object(self._class_name(name), defs[name], "common.json")

    def _add_object(self, class_name: str, schema: dict[str, Any], source_file: str) -> str:
        if class_name in self.classes:
            return class_name
        required = list(schema.get("required", []))
        properties = schema.get("properties", {})
        ordered_names = [name for name in required if name in properties]
        ordered_names.extend(sorted(name for name in properties if name not in required))

        fields: list[FieldSpec] = []
        self.classes[class_name] = ClassSpec(
            name=class_name,
            schema=schema,
            fields=fields,
            comment=schema.get("$comment"),
            extra="forbid" if class_name == "ConfigUpdateSettings" else "ignore",
        )
        for field_name in ordered_names:
            field_schema = properties[field_name]
            annotation = self._annotation(
                field_schema, f"{class_name}{self._class_name(field_name)}", source_file
            )
            if field_name == "payload" and class_name == "FarmEnvelope":
                annotation = "Dict[str, Any]"
            if field_name not in required:
                annotation = self._optional_annotation(annotation)
            if not field_name.isidentifier():
                raise ValueError(f"unsupported field name: {field_name}")
            fields.append(
                FieldSpec(
                    name=field_name,
                    annotation=annotation,
                    required=field_name in required,
                    comment=field_schema.get("description"),
                )
            )
        return class_name

    def _annotation(self, schema: dict[str, Any], name_hint: str, source_file: str) -> str:
        resolved = self._resolve_ref(schema, source_file)
        if "oneOf" in resolved:
            non_null = [item for item in resolved["oneOf"] if item.get("type") != "null"]
            has_null = len(non_null) != len(resolved["oneOf"])
            if len(non_null) != 1 or not has_null:
                raise ValueError(f"unsupported oneOf in {name_hint}")
            return f"Optional[{self._annotation(non_null[0], name_hint, source_file)}]"
        if "const" in resolved:
            return f"Literal[{resolved['const']!r}]"
        if "enum" in resolved:
            values = list(resolved["enum"])
            has_null = None in values
            enum_values = [value for value in values if value is not None]
            enum_name = self._enum_name(name_hint)
            if enum_name not in self.enums:
                self.enums[enum_name] = enum_values
            return f"Optional[{enum_name}]" if has_null else enum_name

        schema_type = resolved.get("type")
        if isinstance(schema_type, list):
            non_null_types = [item for item in schema_type if item != "null"]
            if len(non_null_types) != 1:
                raise ValueError(f"unsupported union type in {name_hint}: {schema_type}")
            inner = dict(resolved)
            inner["type"] = non_null_types[0]
            return f"Optional[{self._annotation(inner, name_hint, source_file)}]"
        if schema_type == "string":
            return self._annotated_scalar("str", resolved)
        if schema_type == "integer":
            return self._annotated_scalar("int", resolved)
        if schema_type == "number":
            return self._annotated_scalar("float", resolved)
        if schema_type == "boolean":
            return "bool"
        if schema_type == "array":
            return f"List[{self._annotation(resolved['items'], name_hint + 'Item', source_file)}]"
        if schema_type == "object":
            properties = resolved.get("properties")
            if properties:
                object_name = (
                    "ConfigUpdateSettings"
                    if name_hint == "ConfigUpdatePayloadSettings"
                    else name_hint
                )
                return self._add_object(object_name, resolved, source_file)
            additional = resolved.get("additionalProperties")
            if isinstance(additional, dict):
                value_type = self._annotation(additional, name_hint + "Value", source_file)
            else:
                value_type = "Any"
            key_type = "str"
            property_names = resolved.get("propertyNames")
            if isinstance(property_names, dict):
                key_type = self._annotation(property_names, name_hint + "Key", source_file)
            return f"Dict[{key_type}, {value_type}]"
        raise ValueError(f"unsupported schema in {name_hint}: {resolved}")

    def _resolve_ref(self, schema: dict[str, Any], source_file: str) -> dict[str, Any]:
        if "$ref" not in schema:
            return schema
        ref = schema["$ref"]
        filename, _, pointer = ref.partition("#/")
        if not filename:
            filename = source_file
        target: Any = self.schemas[filename]
        for part in pointer.split("/"):
            target = target[part]
        merged = dict(target)
        for key, value in schema.items():
            if key != "$ref":
                merged[key] = value
        return merged

    def _annotated_scalar(self, base: str, schema: dict[str, Any]) -> str:
        args: list[str] = []
        mapping = {
            "minimum": "ge",
            "maximum": "le",
            "exclusiveMinimum": "gt",
            "exclusiveMaximum": "lt",
            "minLength": "min_length",
            "maxLength": "max_length",
            "pattern": "pattern",
        }
        for src, dst in mapping.items():
            if src in schema:
                args.append(f"{dst}={schema[src]!r}")
        if not args:
            return base
        return f"Annotated[{base}, Field({', '.join(args)})]"

    @staticmethod
    def _optional_annotation(annotation: str) -> str:
        if annotation.startswith("Optional["):
            return annotation
        return f"Optional[{annotation}]"

    @staticmethod
    def _class_name(raw: str) -> str:
        return "".join(part.capitalize() for part in re.split(r"[^A-Za-z0-9]+", raw) if part)

    @staticmethod
    def _payload_class_name(raw: str) -> str:
        return PythonGenerator._class_name(raw) + "Payload"

    @staticmethod
    def _enum_name(raw: str) -> str:
        if raw.endswith("Enum"):
            return raw
        return raw + "Enum"

    @staticmethod
    def _enum_member(value: str) -> str:
        name = re.sub(r"[^A-Za-z0-9]+", "_", value).upper().strip("_")
        if not name or name[0].isdigit():
            name = "V_" + name
        return name


class Mql5Generator:
    def __init__(self, schemas: dict[str, dict[str, Any]]) -> None:
        self.schemas = schemas

    def generate(self) -> str:
        msg_types = list(self.schemas["envelope.json"]["properties"]["type"]["enum"])
        lines = [*MQL5_HEADER]
        lines.extend(
            [
                "#ifndef FARM_MESSAGES_MQH",
                "#define FARM_MESSAGES_MQH",
                "",
                "#include <Farm/JsonCore.mqh>",
                "",
                "enum ENUM_FARM_MSG_TYPE",
                "{",
            ]
        )
        for msg_type in msg_types:
            lines.append(f"   FARM_MSG_{msg_type},")
        lines.extend(
            [
                "   FARM_MSG_UNKNOWN",
                "};",
                "",
                "struct FarmEnvelope",
                "{",
                "   int                v;",
                "   ENUM_FARM_MSG_TYPE type;",
                "   string             type_raw;",
                "   string             msg_id;",
                "   string             session_id;",
                "   string             ts_server;",
                "   string             ts_sent;",
                "   string             payload_json;",
                "};",
                "",
                "struct FarmPayloadJson",
                "{",
                "   string raw_json;",
                "};",
                "",
                "struct FarmStatePayload",
                "{",
                "   string raw_json;",
                "   bool   margin_level_pct_present;",
                "   bool   margin_level_pct_is_null;",
                "   double margin_level_pct;",
                "};",
                "",
            ]
        )
        for payload in TYPE_TO_PAYLOAD.values():
            if payload == "StatePayload":
                continue
            lines.extend(
                [
                    f"struct Farm{payload}",
                    "{",
                    "   string raw_json;",
                    "};",
                    "",
                ]
            )
        lines.extend(self._helpers(msg_types))
        lines.append("#endif")
        return "\n".join(lines).rstrip() + "\n"

    @staticmethod
    def _helpers(msg_types: list[str]) -> list[str]:
        lines: list[str] = [
            "string FarmMsgTypeToString(const ENUM_FARM_MSG_TYPE v)",
            "{",
            "   switch(v)",
            "   {",
        ]
        for msg_type in msg_types:
            lines.append(f"      case FARM_MSG_{msg_type}: return \"{msg_type}\";")
        lines.extend(
            [
                "      default: return \"UNKNOWN\";",
                "   }",
                "}",
                "",
                "ENUM_FARM_MSG_TYPE FarmMsgTypeFromString(const string s)",
                "{",
            ]
        )
        for msg_type in msg_types:
            lines.append(f"   if(s == \"{msg_type}\") return FARM_MSG_{msg_type};")
        lines.extend(
            [
                "   return FARM_MSG_UNKNOWN;",
                "}",
                "",
                "bool FarmLooksLikeUlid(const string s)",
                "{",
                "   if(StringLen(s) != 26) return false;",
                "   const string alphabet = \"0123456789ABCDEFGHJKMNPQRSTVWXYZ\";",
                "   for(int i = 0; i < StringLen(s); i++)",
                "   {",
                "      if(StringFind(alphabet, ShortToString(StringGetCharacter(s, i))) < 0)",
                "         return false;",
                "   }",
                "   return true;",
                "}",
                "",
                "bool FarmLooksLikeSymbol(const string s)",
                "{",
                "   if(StringLen(s) < 3 || StringLen(s) > 24) return false;",
                "   int dot_count = 0;",
                "   int dot_pos = -1;",
                "   for(int i = 0; i < StringLen(s); i++)",
                "   {",
                "      const ushort ch = StringGetCharacter(s, i);",
                "      const bool upper_digit = (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9');",  # noqa: E501
                "      const bool suffix = (ch >= 'a' && ch <= 'z') || upper_digit;",
                "      if(ch == '.') { dot_count++; dot_pos = i; continue; }",
                "      if(dot_count == 0 && !upper_digit) return false;",
                "      if(dot_count > 0 && !suffix) return false;",
                "   }",
                "   if(dot_count > 1) return false;",
                "   if(dot_count == 1 && (dot_pos < 3 || StringLen(s) - dot_pos - 1 < 1 || StringLen(s) - dot_pos - 1 > 8)) return false;",  # noqa: E501
                "   if(dot_count == 0 && StringLen(s) > 15) return false;",
                "   return true;",
                "}",
                "",
                "bool FarmLooksLikeTsUtc(const string s)",
                "{",
                "   const int n = StringLen(s);",
                "   if(n != 20 && n < 22) return false;",
                "   if(StringGetCharacter(s, n - 1) != 'Z') return false;",
                "   if(StringFind(s, \"+\") >= 0) return false;",
                "   if(StringGetCharacter(s, 4) != '-' || StringGetCharacter(s, 7) != '-' || StringGetCharacter(s, 10) != 'T') return false;",  # noqa: E501
                "   if(StringGetCharacter(s, 13) != ':' || StringGetCharacter(s, 16) != ':') return false;",  # noqa: E501
                "   if(n == 20) return true;",
                "   if(StringGetCharacter(s, 19) != '.') return false;",
                "   const int frac = n - 21;",
                "   return frac >= 1 && frac <= 3;",
                "}",
                "",
                "bool FarmRequireObjectKey(CFarmJsonValue *obj, const string key)",
                "{",
                "   if(obj == NULL || obj.type != FARM_JSON_OBJECT || !obj.Has(key))",
                "   {",
                "      FarmJsonSetError(\"MISSING_REQUIRED\", key);",
                "      return false;",
                "   }",
                "   return true;",
                "}",
                "",
                "bool FarmRequireKeys(CFarmJsonValue *obj, const string &keys[])",
                "{",
                "   for(int i = 0; i < ArraySize(keys); i++)",
                "   {",
                "      if(!FarmRequireObjectKey(obj, keys[i])) return false;",
                "   }",
                "   return true;",
                "}",
                "",
                "bool FarmValidateEnvelopeDoc(CFarmJsonValue *root, FarmEnvelope &out)",
                "{",
                "   if(root == NULL || root.type != FARM_JSON_OBJECT) { FarmJsonSetError(\"EXPECTED_OBJECT\", \"envelope\"); return false; }",  # noqa: E501
                "   string required[] = {\"v\",\"type\",\"msg_id\",\"session_id\",\"ts_server\",\"ts_sent\",\"payload\"};",  # noqa: E501
                "   if(!FarmRequireKeys(root, required)) return false;",
                "   CFarmJsonValue *v = root.Get(\"v\");",
                "   CFarmJsonValue *type = root.Get(\"type\");",
                "   CFarmJsonValue *msg_id = root.Get(\"msg_id\");",
                "   CFarmJsonValue *session_id = root.Get(\"session_id\");",
                "   CFarmJsonValue *ts_server = root.Get(\"ts_server\");",
                "   CFarmJsonValue *ts_sent = root.Get(\"ts_sent\");",
                "   CFarmJsonValue *payload = root.Get(\"payload\");",
                "   if(v.type != FARM_JSON_NUMBER || v.integer_value != 1) { FarmJsonSetError(\"BAD_FIELD\", \"v\"); return false; }",  # noqa: E501
                "   if(type.type != FARM_JSON_STRING) { FarmJsonSetError(\"BAD_FIELD\", \"type\"); return false; }",  # noqa: E501
                "   if(msg_id.type != FARM_JSON_STRING || !FarmLooksLikeUlid(msg_id.string_value)) { FarmJsonSetError(\"BAD_FIELD\", \"msg_id\"); return false; }",  # noqa: E501
                "   if(session_id.type != FARM_JSON_STRING || StringFind(session_id.string_value, \"PERIOD_\") >= 0) { FarmJsonSetError(\"BAD_FIELD\", \"session_id\"); return false; }",  # noqa: E501
                "   if(ts_server.type != FARM_JSON_STRING || !FarmLooksLikeTsUtc(ts_server.string_value)) { FarmJsonSetError(\"BAD_FIELD\", \"ts_server\"); return false; }",  # noqa: E501
                "   if(ts_sent.type != FARM_JSON_STRING || !FarmLooksLikeTsUtc(ts_sent.string_value)) { FarmJsonSetError(\"BAD_FIELD\", \"ts_sent\"); return false; }",  # noqa: E501
                "   if(payload.type != FARM_JSON_OBJECT) { FarmJsonSetError(\"BAD_FIELD\", \"payload\"); return false; }",  # noqa: E501
                "   out.v = 1;",
                "   out.type_raw = type.string_value;",
                "   out.type = FarmMsgTypeFromString(out.type_raw);",
                "   out.msg_id = msg_id.string_value;",
                "   out.session_id = session_id.string_value;",
                "   out.ts_server = ts_server.string_value;",
                "   out.ts_sent = ts_sent.string_value;",
                "   out.payload_json = payload.ToJson();",
                "   return true;",
                "}",
                "",
                "bool FarmParseEnvelope(const string line, FarmEnvelope &out)",
                "{",
                "   CFarmJsonDoc doc;",
                "   if(!doc.Parse(line)) return false;",
                "   const bool ok = FarmValidateEnvelopeDoc(doc.Root(), out);",
                "   doc.Free();",
                "   return ok;",
                "}",
                "",
                "bool FarmSerializeEnvelope(const FarmEnvelope &src, string &out_line)",
                "{",
                "   const string type = (src.type == FARM_MSG_UNKNOWN ? src.type_raw : FarmMsgTypeToString(src.type));",  # noqa: E501
                "   out_line = \"{\"",
                "      + \"\\\"v\\\":\" + IntegerToString(src.v)",
                "      + \",\\\"type\\\":\" + FarmJsonQuoteUtf8(type)",
                "      + \",\\\"msg_id\\\":\" + FarmJsonQuoteUtf8(src.msg_id)",
                "      + \",\\\"session_id\\\":\" + FarmJsonQuoteUtf8(src.session_id)",
                "      + \",\\\"ts_server\\\":\" + FarmJsonQuoteUtf8(src.ts_server)",
                "      + \",\\\"ts_sent\\\":\" + FarmJsonQuoteUtf8(src.ts_sent)",
                "      + \",\\\"payload\\\":\" + src.payload_json + \"}\";",
                "   return true;",
                "}",
                "",
                "bool FarmValidateState(CFarmJsonValue *payload)",
                "{",
                "   string required[] = {\"balance\",\"equity\",\"margin_used\",\"margin_free\",\"margin_level_pct\",\"equity_hwm\",\"day_start_equity\",\"day_pl\",\"day_pl_pct\",\"positions\",\"pending_orders\",\"owned_net\",\"owned_ticket_count\",\"foreign_positions\",\"account_margin_mode\",\"guard\"};",  # noqa: E501
                "   if(!FarmRequireKeys(payload, required)) return false;",
                "   CFarmJsonValue *positions = payload.Get(\"positions\");",
                "   if(positions.type != FARM_JSON_ARRAY) { FarmJsonSetError(\"BAD_FIELD\", \"positions\"); return false; }",  # noqa: E501
                "   for(int i = 0; i < positions.Size(); i++)",
                "   {",
                "      CFarmJsonValue *pos = positions.At(i);",
                "      if(pos == NULL || pos.type != FARM_JSON_OBJECT) { FarmJsonSetError(\"BAD_FIELD\", \"positions[]\"); return false; }",  # noqa: E501
                "      string pos_required[] = {\"ticket\",\"symbol\",\"side\",\"volume\",\"price_open\",\"sl\",\"tp\",\"profit\",\"swap\",\"magic\",\"time_open\"};",  # noqa: E501
                "      if(!FarmRequireKeys(pos, pos_required)) return false;",
                "      CFarmJsonValue *sl = pos.Get(\"sl\");",
                "      if(sl.type == FARM_JSON_NUMBER && sl.number_value <= 0.0) { FarmJsonSetError(\"BAD_FIELD\", \"sl\"); return false; }",  # noqa: E501
                "      CFarmJsonValue *comment = pos.Get(\"comment\");",
                "      if(comment != NULL && comment.type != FARM_JSON_NULL && comment.type != FARM_JSON_STRING) { FarmJsonSetError(\"BAD_FIELD\", \"comment\"); return false; }",  # noqa: E501
                "   }",
                "   CFarmJsonValue *owned_net = payload.Get(\"owned_net\");",
                "   if(owned_net.type != FARM_JSON_OBJECT) { FarmJsonSetError(\"BAD_FIELD\", \"owned_net\"); return false; }",  # noqa: E501
                "   for(int i = 0; i < owned_net.Size(); i++)",
                "   {",
                "      if(!FarmLooksLikeSymbol(owned_net.KeyAt(i))) { FarmJsonSetError(\"BAD_FIELD\", \"owned_net\"); return false; }",  # noqa: E501
                "   }",
                "   return true;",
                "}",
                "",
                "bool FarmValidatePayload(const ENUM_FARM_MSG_TYPE msg_type, CFarmJsonValue *payload)",  # noqa: E501
                "{",
                "   if(payload == NULL || payload.type != FARM_JSON_OBJECT) { FarmJsonSetError(\"EXPECTED_OBJECT\", \"payload\"); return false; }",  # noqa: E501
                "   if(msg_type == FARM_MSG_UNKNOWN) return true;",
                "   if(msg_type == FARM_MSG_BAR)",
                "   {",
                "      if(!FarmRequireObjectKey(payload, \"is_final\")) return false;",
                "      CFarmJsonValue *is_final = payload.Get(\"is_final\");",
                "      if(is_final.type != FARM_JSON_BOOL || !is_final.bool_value) { FarmJsonSetError(\"BAD_FIELD\", \"is_final\"); return false; }",  # noqa: E501
                "   }",
                "   if(msg_type == FARM_MSG_HELLO)",
                "   {",
                "      if(!FarmRequireObjectKey(payload, \"token\")) return false;",
                "      CFarmJsonValue *account = payload.Get(\"account\");",
                "      if(account != NULL && account.type == FARM_JSON_OBJECT)",
                "      {",
                "         CFarmJsonValue *mode = account.Get(\"margin_mode\");",
                "         if(mode != NULL && mode.type == FARM_JSON_STRING && mode.string_value == \"retail_hedging\") { FarmJsonSetError(\"BAD_FIELD\", \"account.margin_mode\"); return false; }",  # noqa: E501
                "      }",
                "   }",
                "   if(msg_type == FARM_MSG_STATE && !FarmValidateState(payload)) return false;",
                "   if(msg_type == FARM_MSG_RISK_DIRECTIVE)",
                "   {",
                "      if(!FarmRequireObjectKey(payload, \"scale_factor\")) return false;",
                "      CFarmJsonValue *scale = payload.Get(\"scale_factor\");",
                "      if(scale.type != FARM_JSON_NUMBER || scale.number_value < 0.0 || scale.number_value > 1.0) { FarmJsonSetError(\"BAD_FIELD\", \"scale_factor\"); return false; }",  # noqa: E501
                "   }",
                "   if(msg_type == FARM_MSG_CONFIG_UPDATE)",
                "   {",
                "      CFarmJsonValue *settings = payload.Get(\"settings\");",
                "      if(settings == NULL || settings.type != FARM_JSON_OBJECT) { FarmJsonSetError(\"MISSING_REQUIRED\", \"settings\"); return false; }",  # noqa: E501
                "      for(int i = 0; i < settings.Size(); i++)",
                "      {",
                "         const string key = settings.KeyAt(i);",
                "         if(key != \"verbose_log\" && key != \"heartbeat_sec\" && key != \"state_interval_sec\" && key != \"bar_backfill_count\") { FarmJsonSetError(\"UNKNOWN_FIELD\", \"settings.\" + key); return false; }",  # noqa: E501
                "      }",
                "   }",
                "   return true;",
                "}",
                "",
                "bool FarmParsePayloadJson(const ENUM_FARM_MSG_TYPE msg_type, const string json, string &out_json)",  # noqa: E501
                "{",
                "   CFarmJsonDoc doc;",
                "   if(!doc.Parse(json)) return false;",
                "   if(!FarmValidatePayload(msg_type, doc.Root())) { doc.Free(); return false; }",
                "   out_json = doc.Root().ToJson();",
                "   doc.Free();",
                "   return true;",
                "}",
                "",
                "bool FarmParseState(const string json, FarmStatePayload &out)",
                "{",
                "   CFarmJsonDoc doc;",
                "   if(!doc.Parse(json)) return false;",
                "   if(!FarmValidateState(doc.Root())) { doc.Free(); return false; }",
                "   out.raw_json = doc.Root().ToJson();",
                "   CFarmJsonValue *ml = doc.Root().Get(\"margin_level_pct\");",
                "   out.margin_level_pct_present = (ml != NULL);",
                "   out.margin_level_pct_is_null = (ml != NULL && ml.type == FARM_JSON_NULL);",
                "   out.margin_level_pct = (ml != NULL && ml.type == FARM_JSON_NUMBER ? ml.number_value : 0.0);",  # noqa: E501
                "   doc.Free();",
                "   return true;",
                "}",
                "",
                "bool FarmSerializeState(const FarmStatePayload &src, string &out_json)",
                "{",
                "   out_json = src.raw_json;",
                "   return out_json != \"\";",
                "}",
                "",
            ]
        )
        payload_functions = {
            "Hello": "HELLO",
            "HelloAck": "HELLO_ACK",
            "Heartbeat": "HEARTBEAT",
            "HeartbeatAck": "HEARTBEAT_ACK",
            "Bar": "BAR",
            "Intent": "INTENT",
            "IntentAck": "INTENT_ACK",
            "ExecReport": "EXEC_REPORT",
            "RiskDirective": "RISK_DIRECTIVE",
            "ConfigUpdate": "CONFIG_UPDATE",
            "Error": "ERROR",
        }
        for name, msg_type in payload_functions.items():
            lines.extend(
                [
                    f"bool FarmParse{name}(const string json, Farm{name}Payload &out)",
                    "{",
                    f"   return FarmParsePayloadJson(FARM_MSG_{msg_type}, json, out.raw_json);",
                    "}",
                    "",
                    f"bool FarmSerialize{name}(const Farm{name}Payload &src, string &out_json)",
                    "{",
                    "   out_json = src.raw_json;",
                    "   return out_json != \"\";",
                    "}",
                    "",
                ]
            )
        return lines


def load_schemas() -> dict[str, dict[str, Any]]:
    return {
        path.name: json.loads(path.read_text(encoding="utf-8"))
        for path in sorted(SCHEMA_DIR.glob("*.json"))
    }


def atomic_write(path: Path, content: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    with tempfile.NamedTemporaryFile(
        "w", encoding="utf-8", newline="\n", delete=False, dir=path.parent
    ) as fh:
        fh.write(content)
        tmp = Path(fh.name)
    tmp.replace(path)


def sample_for(
    schema: dict[str, Any],
    schemas: dict[str, dict[str, Any]],
    *,
    minimal: bool,
    source_file: str = "common.json",
) -> Any:
    schema = resolve_ref(schema, schemas, source_file)
    if "oneOf" in schema:
        non_null = [item for item in schema["oneOf"] if item.get("type") != "null"]
        return (
            sample_for(non_null[0], schemas, minimal=minimal, source_file=source_file)
            if non_null
            else None
        )
    if "const" in schema:
        return schema["const"]
    if "enum" in schema:
        return next(value for value in schema["enum"] if value is not None)
    schema_type = schema.get("type")
    if isinstance(schema_type, list):
        non_null = [item for item in schema_type if item != "null"]
        if "null" in schema_type and minimal:
            return None
        return sample_for(
            {**schema, "type": non_null[0]},
            schemas,
            minimal=minimal,
            source_file=source_file,
        )
    if schema_type == "string":
        pattern = schema.get("pattern", "")
        if pattern == "^[0-9A-HJKMNP-TV-Z]{26}$":
            return ULID
        if pattern.startswith("^acct-"):
            return SESSION_ID
        if pattern.startswith("^[A-Z0-9]{3,15}"):
            return SYMBOL
        if pattern == "^[A-Z]{3}$":
            return "USD"
        if pattern == "^[0-9]+\\.[0-9]+\\.[0-9]+$":
            return "1.0.0"
        if pattern == "^[A-Z][A-Z0-9_]{2,63}$":
            return "BAD_REQUEST"
        if pattern.startswith("^[a-z0-9_]"):
            return "trend_v1"
        if pattern.startswith("^sha256:"):
            return "sha256:abcdef12"
        if "Z$" in pattern:
            return TS
        return "value"
    if schema_type == "integer":
        return max(1, int(schema.get("minimum", 1)))
    if schema_type == "number":
        minimum = schema.get("exclusiveMinimum", schema.get("minimum", 1.0))
        if minimum == 0:
            return 1.0
        if minimum < 0:
            return 0.0
        return float(minimum)
    if schema_type == "boolean":
        return True
    if schema_type == "array":
        if minimal:
            return []
        return [sample_for(schema["items"], schemas, minimal=minimal, source_file=source_file)]
    if schema_type == "object":
        props = schema.get("properties", {})
        required = list(schema.get("required", []))
        names = (
            required
            if minimal
            else [*required, *sorted(name for name in props if name not in required)]
        )
        if props:
            return {
                name: sample_for(props[name], schemas, minimal=minimal, source_file=source_file)
                for name in names
                if name in props
            }
        additional = schema.get("additionalProperties")
        if isinstance(additional, dict):
            return {
                SYMBOL: sample_for(additional, schemas, minimal=minimal, source_file=source_file)
            }
        return {}
    raise ValueError(f"cannot make sample for schema: {schema}")


def resolve_ref(
    schema: dict[str, Any], schemas: dict[str, dict[str, Any]], source_file: str
) -> dict[str, Any]:
    if "$ref" not in schema:
        return schema
    filename, _, pointer = schema["$ref"].partition("#/")
    if not filename:
        filename = source_file
    target: Any = schemas[filename]
    for part in pointer.split("/"):
        target = target[part]
    merged = dict(target)
    for key, value in schema.items():
        if key != "$ref":
            merged[key] = value
    return merged


def envelope_for(msg_type: str, payload: dict[str, Any]) -> dict[str, Any]:
    return OrderedDict(
        [
            ("v", 1),
            ("type", msg_type),
            ("msg_id", ULID),
            ("session_id", SESSION_ID),
            ("ts_server", TS),
            ("ts_sent", TS_MS),
            ("payload", payload),
        ]
    )


def dumps_json(data: Any) -> str:
    return json.dumps(data, ensure_ascii=False, sort_keys=False, separators=(",", ":")) + "\n"


def write_fixtures(schemas: dict[str, dict[str, Any]]) -> None:
    if FIXTURE_DIR.exists():
        shutil.rmtree(FIXTURE_DIR)
    (FIXTURE_DIR / "invalid").mkdir(parents=True)
    for name in PAYLOAD_FILES:
        msg_type = name.upper()
        schema_file = f"{name}.json"
        payload = sample_for(schemas[schema_file], schemas, minimal=False, source_file=schema_file)
        minimal_payload = sample_for(
            schemas[schema_file], schemas, minimal=True, source_file=schema_file
        )
        extra_payload = dict(payload)
        extra_payload["x_forward_compat"] = "ignored"
        atomic_write(
            FIXTURE_DIR / f"{name}.valid.json", dumps_json(envelope_for(msg_type, payload))
        )
        atomic_write(
            FIXTURE_DIR / f"{name}.valid.min.json",
            dumps_json(envelope_for(msg_type, minimal_payload)),
        )
        atomic_write(
            FIXTURE_DIR / f"{name}.valid.extra.json",
            dumps_json(envelope_for(msg_type, extra_payload)),
        )

    invalid_cases: dict[str, dict[str, Any]] = {}
    base = envelope_for(
        "HELLO", sample_for(schemas["hello.json"], schemas, minimal=False, source_file="hello.json")
    )
    bad = dict(base)
    bad["msg_id"] = "202607261430000000"
    invalid_cases["envelope.msgid_18digits.json"] = bad
    bad = dict(base)
    bad["session_id"] = "acct-8123456-EURUSD.iux-PERIOD_H1"
    invalid_cases["envelope.session_period_prefix.json"] = bad
    bad = dict(base)
    bad["ts_server"] = "2026-07-26T14:30:00+07:00"
    invalid_cases["envelope.ts_offset_not_z.json"] = bad

    state = envelope_for(
        "STATE", sample_for(schemas["state.json"], schemas, minimal=False, source_file="state.json")
    )
    state["payload"]["positions"][0]["sl"] = 0
    invalid_cases["state.sl_zero.json"] = state
    state_bad_map = envelope_for(
        "STATE", sample_for(schemas["state.json"], schemas, minimal=False, source_file="state.json")
    )
    state_bad_map["payload"]["owned_net"] = {"PERIOD_H1": 0.2}
    invalid_cases["state.owned_net_bad_symbol_key.json"] = state_bad_map

    risk = envelope_for(
        "RISK_DIRECTIVE",
        sample_for(
            schemas["risk_directive.json"],
            schemas,
            minimal=False,
            source_file="risk_directive.json",
        ),
    )
    risk["payload"]["scale_factor"] = 1.5
    invalid_cases["risk_directive.scale_above_one.json"] = risk

    bar = envelope_for(
        "BAR", sample_for(schemas["bar.json"], schemas, minimal=False, source_file="bar.json")
    )
    bar["payload"]["is_final"] = False
    invalid_cases["bar.is_final_false.json"] = bar

    hello = envelope_for(
        "HELLO", sample_for(schemas["hello.json"], schemas, minimal=False, source_file="hello.json")
    )
    hello["payload"]["account"]["margin_mode"] = "retail_hedging"
    invalid_cases["hello.margin_mode_lowercase.json"] = hello

    config = envelope_for(
        "CONFIG_UPDATE",
        sample_for(
            schemas["config_update.json"], schemas, minimal=False, source_file="config_update.json"
        ),
    )
    config["payload"]["settings"]["max_lot_per_order"] = 0.5
    invalid_cases["config_update.unknown_setting.json"] = config

    for name, data in sorted(invalid_cases.items()):
        atomic_write(FIXTURE_DIR / "invalid" / name, dumps_json(data))


def write_python_models(schemas: dict[str, dict[str, Any]]) -> None:
    generator = PythonGenerator(schemas)
    content = generator.generate()
    atomic_write(PY_OUT_DIR / "models.py", content)
    symbols = generator.public_symbols()
    init = "\n".join(
        [
            "# GENERATED by tools/codegen.py from contracts/schema/ -- DO NOT EDIT",
            "# Edit schema and rerun `python tools/task.py codegen`.",
            "",
            "from .models import (",
            *[f"    {symbol}," for symbol in symbols],
            ")",
            "",
            "__all__ = [",
            *[f"    {symbol!r}," for symbol in symbols],
            "]",
            "",
        ]
    )
    atomic_write(PY_OUT_DIR / "__init__.py", init)


def write_mql5_models(schemas: dict[str, dict[str, Any]]) -> None:
    content = Mql5Generator(schemas).generate()
    atomic_write(MQL5_OUT_DIR / "FarmMessages.mqh", content)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser()
    parser.parse_args(argv)
    schemas = load_schemas()
    write_python_models(schemas)
    write_mql5_models(schemas)
    write_fixtures(schemas)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
